def solve(inp, bg, noise):
    R,C = len(inp), len(inp[0])
    # structure cells = cells not bg and not noise
    out = [row[:] for row in inp]
    # find connected components of structure cells, get bounding boxes
    from collections import deque
    seen = [[False]*C for _ in range(R)]
    for r in range(R):
        for c in range(C):
            if inp[r][c] not in (bg, noise) and not seen[r][c]:
                col = inp[r][c]
                q = deque([(r,c)]); seen[r][c]=True
                cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<R and 0<=ny<C and not seen[nx][ny] and inp[nx][ny]==col:
                            seen[nx][ny]=True; q.append((nx,ny))
                rs=[x for x,_ in cells]; cs=[y for _,y in cells]
                r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
                for rr in range(r0,r1+1):
                    for cc in range(c0,c1+1):
                        if inp[rr][cc] in noise:
                            out[rr][cc]=col
    for r in range(R):
        for c in range(C):
            if inp[r][c] in noise:
                out[r][c]=bg
    return out

